# coding: utf-8
from lesson_authoring import entry as E
P=[['拉丁语 par','相等的、相称的']]
C=P+[['拉丁 comparare → 法语 comparer','把事物相提并论、比较'],['英语 compare','比较异同；把……比作']]
R=P+[['古法语 per／peir → 英语 peer','地位相等的人；同辈、同等者']]
G=P+[['古法语 parage → desparagier','地位、门第 → 使地位下降、贬低'],['英语 disparage','贬损、轻视']]
W=[
E('compare','英 /kəmˈpeə/；美 /kəmˈper/','比较；把……比作；比得上','把两样东西放到同一个尺度前，看看哪里一样、哪里不同。','拉丁 com-“一起” + par“相等”形成比较相关词；经法语 comparer 进入英语。不是 prepare 那条“准备”的 parare。',C,'compare 并不要求结果相等。比较两台电脑可能发现一台快、一台便宜。compare A to B 也可作比喻，把 A 比成 B；with 常用于逐项比较，但实际用法有交叉，不必当成两条不能跨越的规定。','compare prices；compare A with B；compare notes；nothing compares to。','compare 研究相似与差异，contrast 特别突出差异。比较不是自动宣布哪一个更好。',('Compare the two plans before making a decision.','做决定前，先比较一下这两个方案。'),('She compared the city at night to a sea of stars.','她把夜晚的城市比作一片星海。'),sources=['https://www.etymonline.com/word/compare','https://en.wiktionary.org/wiki/compare']),
E('comparison','/kəmˈpærɪsən/','比较、对照；比喻性的相提并论','把比较这件事当成一个过程或一份结果来谈。','经法语 comparaison 来自拉丁 comparatio；英语记录早于 compare，不是现代英语简单给 compare 加 -ison。',P+[['拉丁 comparare → comparatio','比较 → 比较这一行为'],['法语 comparaison → 英语 comparison','比较、对照']],'make a comparison 是作比较；by comparison 是“相比之下”；a fair comparison 是双方条件合理、不是拿苹果与橘子硬比。它可以出现在研究表格里，也可以是一句日常评论。','a comparison between A and B；in comparison with；by comparison。','comparison 是比较本身，competition 是比赛或竞争；可以比较两个东西而没有比赛。',('The table provides a comparison of the available options.','表格对照了现有的几个选项。'),('Our old apartment seems tiny by comparison.','相比之下，我们以前的公寓显得很小。'),sources=['https://www.etymonline.com/word/comparison','https://en.wiktionary.org/wiki/comparison']),
E('comparable','英 /ˈkɒmpərəbəl/；美 /ˈkɑːmpərəbəl/','可比较的；相当的、类似的','放到一起比较是有意义的，或者比较后发现水平差不多。','经法语来自拉丁 comparabilis；现代可联系 compare + -able，但历史上是借来的形容词。',P+[['拉丁 comparare → comparabilis','比较 → 可比较的'],['法语 comparable → 英语 comparable','可比较的、相当的']],'comparable prices 常指价格差不多；comparable data 强调数据条件相近，可以合理比较。这个词不必表示完全相同。读技术报告时尤其要看它说的是“有比较基础”还是“水平相近”。','comparable to／with；comparable prices；directly comparable data。','comparable 是可以比或差不多，comparative 是比较性的。两者只差一点拼写，用途却不同。',('The two schools offer courses of comparable quality.','两所学校提供的课程质量相当。'),('These results are not directly comparable because the methods differ.','由于方法不同，这些结果不能直接比较。'),sources=['https://www.etymonline.com/word/comparable','https://en.wiktionary.org/wiki/comparable']),
E('comparative','/kəmˈpærətɪv/','比较的；相对而言的；比较级的','不是单独下判断，而是放在别的东西旁边才得出的判断。','来自法语 comparatif、拉丁 comparativus，与 comparare“比较”有关。',P+[['拉丁 comparativus → 法语 comparatif','与比较有关的'],['英语 comparative','比较的；相对的；语法比较级的']],'a comparative study 是把几种对象放在一起研究；comparative comfort 是相对于别的处境还算舒适，未必绝对舒服。语法中 bigger 是 big 的 comparative form，这一用法也是“拿来比”的意思。','comparative analysis；comparative ease；the comparative form。','comparable 说对象可比，comparative 说方法或判断涉及比较。relative 与它在“相对的”这一义上接近。',('The article presents a comparative study of three cities.','文章对三座城市进行了比较研究。'),('After months in a tent, they enjoyed the comparative comfort of a small cabin.','住了几个月帐篷后，他们很享受小木屋相对舒适的条件。'),sources=['https://www.etymonline.com/word/comparative','https://en.wiktionary.org/wiki/comparative']),
E('comparatively','/kəmˈpærətɪvli/','比较而言；相对地','把判断的尺子亮出来：和别的地方、时间或情况一比，是这样的。','comparative + -ly，表示比较之下的程度。',C+[['同族形容词 comparative + -ly','相对而言、比较之下']],'comparatively cheap 是相对便宜，不一定真的花钱少。比如一间昂贵地段的房子，比周围其他房子便宜一些，也能用这个词。它给判断留下参照条件，避免说成绝对结论。','comparatively small；comparatively easy；comparatively little。','comparatively 强调与参照物相比；extremely 则直接强调程度很高。',('Public transport is comparatively cheap here.','这里的公共交通相对便宜。'),('The second task was comparatively easy.','第二项任务比较容易。'),sources=['https://en.wiktionary.org/wiki/comparatively','https://www.etymonline.com/word/comparative']),
E('incomparable','英 /ɪnˈkɒmpərəbəl/；美 /ɪnˈkɑːmpərəbəl/','无与伦比的；无法相比的','好到找不到同一水平的对手，常是很强烈的赞美。','拉丁 in-“不” + comparabilis；经法语或直接从拉丁语借入，现代能联系 in- + comparable。',P+[['拉丁 incomparabilis','无法与之匹敌的'],['法语／英语 incomparable','无与伦比的']],'incomparable 常用于赞美才能、美景、体验：不是说不许比较，而是说没有谁比得上。谈两份数据因条件不同而不能比较时，not comparable 往往比这个带赞美色彩的词更清楚。','incomparable beauty；an incomparable performer；incomparable skill。','incomparable 通常是夸奖，incompatible 是不兼容、无法共存，不能混用。',('The guide praised the valley’s incomparable beauty.','导游盛赞山谷无与伦比的美。'),('Her timing made her an incomparable comic performer.','她对节奏的把握使她成为一位无与伦比的喜剧演员。'),sources=['https://www.etymonline.com/word/incomparable','https://en.wiktionary.org/wiki/incomparable']),
E('par','英 /pɑː/；美 /pɑːr/','同等水平；正常标准；高尔夫标准杆数','先画一条基准线，看实际表现有没有达到它。','来自拉丁 par“相等、相称”；从相等关系发展到作为参照的标准。',P+[['英语 par','相等、同等价值；后来指标准水平']],'on a par with 是与……不相上下；below par 在日常语境中常说表现不佳。高尔夫中的 par 则是标准杆数，杆数低于标准通常更好。因此同样的 below par，要看是在评价一般表现还是报高尔夫成绩。','on a par with；below par；up to par；par for the course。','par 是基准，average 是平均值，二者并不在所有场景相等。par for the course 常说“这种情况很正常、早料到了”。',('The new model is on a par with its more expensive competitors.','新款的水平与那些更贵的竞品不相上下。'),('My work was below par because I had barely slept.','因为几乎没睡觉，我那天的工作表现不佳。'),sources=['https://www.etymonline.com/word/par','https://en.wiktionary.org/wiki/par']),
E('parity','/ˈpærəti/','同等、对等；平等水平','两边终于站到同一条水平线上，不再一边高一边低。','经法语 parité 来自拉丁 paritas，源于 par“相等”。另一个医学同形词与生育有关，不沿此路线。',P+[['拉丁 paritas → 法语 parité','相等的状态'],['英语 parity','对等、同等水平']],'pay parity 是薪酬达到同等水平，parity with competitors 是与竞争者不相上下。它通常讨论某个明确维度的对等，不表示两方在所有方面完全一样。数学、计算机还有奇偶性相关的专门用法，阅读时按领域分清。','pay parity；achieve parity with；parity between groups。','equality 是更宽泛的平等，parity 常强调可比较的水平或待遇达到一致。',('The agreement aims to achieve pay parity between the two groups.','这项协议旨在使两组人的薪酬达到同等水平。'),('The smaller company has reached parity with its rival in customer satisfaction.','这家较小的公司在客户满意度上已与对手持平。'),sources=['https://en.wiktionary.org/wiki/parity','https://www.etymonline.com/word/parity']),
]
